function identifyQuestionFor(level,questionIndex){const target=IDENTIFY_QUESTION_WORDS[((level-1)*10+questionIndex)%IDENTIFY_QUESTION_WORDS.length],distractors=[],usedIcons=new Set([target.icon]);for(const entry of IDENTIFY_WORDS.filter(candidate=>candidate.word!==target.word).sort(()=>Math.random()-.5)){if(usedIcons.has(entry.icon))continue;distractors.push(entry);usedIcons.add(entry.icon);if(distractors.length===3)break}return{target,options:[...distractors,target].sort(()=>Math.random()-.5)}}
