const NUMBER_ONES=["","one","two","three","four","five","six","seven","eight","nine"],NUMBER_TEENS=["ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"],NUMBER_TENS=["","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"],NUMBER_SCALES=["","thousand","million","billion","trillion","quadrillion","quintillion","sextillion","septillion","octillion","nonillion","decillion","undecillion","duodecillion","tredecillion","quattuordecillion","quindecillion","sexdecillion","septendecillion","octodecillion","novemdecillion","vigintillion"];
