 const finish=()=>{if(generation!==additionAnimationGeneration)return;window.clearInterval(additionAnimationTimer);additionAnimationTimer=0;$("addition-board").classList.remove("is-animating");updateAdditionTotal(answer,objects);$("addition-question").textContent=`${first} ${mathOperation().symbol} ${second} = ${answer}`;$("addition-feedback").textContent=message};
