function renderQuizLevels(){const config=QUIZZES[quizKey],start=quizLevelPage*10+1,unlocked=quizUnlockedLevel(quizKey),grid=$("quiz-level-grid");$("quiz-levels-title").textContent=`${config.icon} ${config.title}`;$("quiz-levels-intro").textContent=`${config.intro} Finish 10 questions to unlock the next level.`;$("quiz-page-label").textContent=`Levels ${start}–${start+9}`;$("quiz-previous").disabled=quizLevelPage===0;$("quiz-level-feedback").textContent=quizLevelMessage;
 grid.innerHTML=Array.from({length:10},(_,index)=>{const level=start+index,locked=level>unlocked,done=level<unlocked;return `<button class="choice-card english-identify-level-card" type="button" data-quiz-level="${level}" aria-label="Level ${level}${locked?", locked":done?", completed":""}"${locked?" disabled":""}><span class="choice-icon" aria-hidden="true">${locked?"🔒":done?"✅":STORY_LEVEL_ICONS[index]}</span><span class="choice-label">Level ${level}<small>${locked?"Finish the previous level":`${config.levelInfo(level)} · ${storyDifficulty(level)}`}</small></span></button>`}).join("");
 grid.querySelectorAll("[data-quiz-level]:not(:disabled)").forEach(button=>button.onclick=()=>startQuizLevel(Number(button.dataset.quizLevel)))}
function startQuizLevel(level){if(level>quizUnlockedLevel(quizKey))return;stopSpeech();quizLevel=level;quizIndex=0;quizQuestions=QUIZZES[quizKey].questions(level);hideScreens();$("quiz-play").hidden=false;renderQuizQuestion()}
function renderQuizQuestion(){window.clearTimeout(quizResetTimer);quizAnswered=false;quizPlaced=[];const question=quizQuestions[quizIndex],options=$("quiz-options"),order=question.type==="order";
 $("quiz-title").textContent=QUIZZES[quizKey].title;$("quiz-counter").textContent=`Level ${quizLevel} (${storyDifficulty(quizLevel)}) · Question ${quizIndex+1} of 10`;$("quiz-progress-bar").style.width=`${quizIndex*10}%`;$("quiz-picture").textContent=question.picture;$("quiz-picture").hidden=!question.picture;$("quiz-question").innerHTML=question.prompt;$("quiz-feedback").textContent=order?"Tap the words one by one!":"Choose the correct answer!";$("quiz-next").disabled=true;$("quiz-next").textContent=quizIndex===9?`Next level ${quizLevel+1} ➜`:"Next question ➜";
 options.hidden=order;$("quiz-builder").hidden=!order;options.innerHTML="";options.classList.toggle("is-text",question.kind==="text");
 if(order)renderQuizSentence();else question.options.forEach((option,index)=>{const button=document.createElement("button");button.type="button";button.className="english-identify-option quiz-option";button.dataset.letter="ABCD"[index];button.setAttribute("aria-label",option.aria);button.innerHTML=`<span>${option.html}</span>`;button.onclick=()=>chooseQuizOption(button,option.value);options.appendChild(button)});
 say(question.speech)}
function chooseQuizOption(button,value){const question=quizQuestions[quizIndex];if(quizAnswered||!question)return;$("quiz-options").querySelectorAll("button").forEach(option=>option.classList.remove("is-wrong"));if(value!==question.answer){button.classList.add("is-wrong");$("quiz-feedback").textContent="Not quite! Try again.";say(["Not quite. Try again."]);return}button.classList.add("is-correct");$("quiz-options").querySelectorAll("button").forEach(option=>option.disabled=true);finishQuizQuestion()}
function finishQuizQuestion(){const question=quizQuestions[quizIndex];quizAnswered=true;$("quiz-progress-bar").style.width=`${(quizIndex+1)*10}%`;$("quiz-feedback").textContent=quizIndex===9?`${question.success.text} Level ${quizLevel} complete!`:question.success.text;$("quiz-next").disabled=false;say(quizIndex===9?[...question.success.speech,`Level ${quizLevel} complete!`]:question.success.speech)}
function renderQuizSentence(){const question=quizQuestions[quizIndex],sentence=$("quiz-sentence"),tiles=$("quiz-tiles");sentence.classList.remove("is-wrong");sentence.classList.toggle("is-correct",quizAnswered);
 sentence.innerHTML=quizPlaced.length?quizPlaced.map((tile,slot)=>`<button type="button" class="quiz-placed" data-slot="${slot}" aria-label="Remove ${question.tiles[tile]}"${quizAnswered?" disabled":""}>${question.tiles[tile]}</button>`).join(""):'<span class="quiz-sentence-hint">Your sentence goes here ✨</span>';
 tiles.innerHTML=question.tiles.map((word,tile)=>`<button type="button" class="quiz-tile" data-tile="${tile}"${quizPlaced.includes(tile)||quizAnswered?" disabled":""}>${word}</button>`).join("");$("quiz-clear").disabled=quizAnswered||!quizPlaced.length;
 sentence.querySelectorAll("[data-slot]").forEach(button=>button.onclick=()=>{if(quizAnswered)return;quizPlaced.splice(Number(button.dataset.slot),1);renderQuizSentence()});
 tiles.querySelectorAll("[data-tile]").forEach(button=>button.onclick=()=>placeQuizTile(Number(button.dataset.tile)))}
function placeQuizTile(tile){const question=quizQuestions[quizIndex];if(quizAnswered||quizPlaced.includes(tile))return;window.clearTimeout(quizResetTimer);quizPlaced.push(tile);renderQuizSentence();if(quizPlaced.length<question.tiles.length){say([question.tiles[tile].replace(/[.!?]$/,"")]);return}
 if(quizPlaced.map(index=>question.tiles[index]).join(" ")===question.answer){finishQuizQuestion();renderQuizSentence();return}
 $("quiz-sentence").classList.add("is-wrong");$("quiz-feedback").textContent="Almost! Listen to the sentence and try again.";say(["Almost! Listen.",question.answer]);const current=quizIndex;quizResetTimer=window.setTimeout(()=>{if(current!==quizIndex||quizAnswered||$("quiz-play").hidden)return;quizPlaced=[];renderQuizSentence()},1600)}
function hearQuizQuestion(){const question=quizQuestions[quizIndex];if(!question)return;say(question.type==="order"&&quizLevel>4?["Tap the words in the right order.",question.answer]:question.speech)}
function advanceQuiz(){if(!quizAnswered)return;stopSpeech();if(quizIndex<9){quizIndex++;renderQuizQuestion();return}if(quizLevel>=quizUnlockedLevel(quizKey)){quizUnlocked[quizKey]=quizLevel+1;saveQuizProgress()}const next=quizLevel+1;quizLevelPage=Math.floor((next-1)/10);startQuizLevel(next);const welcome=`Great job! Welcome to level ${next}.`;$("quiz-feedback").textContent=welcome;say([welcome,...quizQuestions[0].speech])}
